INSERT INTO `room_type` (`id`, `type_name`, `price`, `area`, `bed_type`, `max_guests`, `description`, `facilities`, `weight`, `status`, `create_time`, `update_time`, `flag`) VALUES
(1, '标准单人间', 258.00, 20, '1.5m 单人床', 1, '简约静谧的单人商务客房，配备独立办公区与高速WiFi，适合单人差旅出行。', '高速WiFi,高清电视,变频空调,吹风机,电热水壶', 100, 1, DATE_SUB(NOW(), INTERVAL 180 DAY), NOW(), 0),
(2, '标准双床房', 328.00, 28, '两张 1.2m 单人床', 2, '通透实用的经典双床布局，干湿分离卫浴，适合同事同行或好友结伴出游。', '高速WiFi,高清电视,变频空调,电热水壶,吹风机,书桌', 110, 1, DATE_SUB(NOW(), INTERVAL 180 DAY), NOW(), 0),
(3, '豪华大床房', 398.00, 34, '1.8m 特大床', 2, '宽敞明亮的城市景大床房，精选乳胶床垫与含双人自助早餐，带来深度好眠体验。', '高速WiFi,高清电视,变频空调,冰箱,含双早,吹风机,浴袍', 130, 1, DATE_SUB(NOW(), INTERVAL 180 DAY), NOW(), 0),
(4, '行政套房', 598.00, 52, '2.0m 尊享大床', 2, '独立会客厅与主卧分区设计，高楼层全景落地窗，配观景浴缸、迷你吧与行政礼遇。', '高速WiFi,智能电视,独立客厅,观景浴缸,冰箱,Minibar,保险箱,含双早,熨斗', 150, 1, DATE_SUB(NOW(), INTERVAL 180 DAY), NOW(), 0),
(5, '家庭房', 498.00, 42, '1.8m 大床 + 1.2m 儿童床', 3, '专为一家三口打造的温馨亲子空间，配备儿童洗漱用品、小帐篷及独立观景阳台。', '高速WiFi,高清电视,变频空调,冰箱,儿童洗漱套装,吹风机,含双早', 140, 1, DATE_SUB(NOW(), INTERVAL 180 DAY), NOW(), 0);
