INSERT INTO `review` (`id`, `user_id`, `order_id`, `room_type_id`, `content`, `score`, `is_anonymous`, `status`, `reply`, `reply_time`, `create_time`, `update_time`, `flag`) VALUES
(1, 1, 1, 3, '豪华大床房床垫很舒服，隔音效果出乎意料的好，早餐种类也很丰富！', 5, 0, 1, '非常感谢您的五星好评，期待您下次商旅再次光临逸云酒店！', CONCAT(DATE_SUB(CURDATE(), INTERVAL 1 DAY), ' 10:00:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 2 DAY), ' 16:20:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 1 DAY), ' 10:00:00'), 0),
(2, 4, 2, 5, '带小朋友住家庭房太合适了，房间里有儿童洗漱套装和小帐篷，孩子非常喜欢。', 5, 0, 1, '看到小朋友住得开心我们也很欣慰，欢迎一家人常来！', CONCAT(DATE_SUB(CURDATE(), INTERVAL 2 DAY), ' 10:00:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 3 DAY), ' 16:20:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 2 DAY), ' 10:00:00'), 0),
(3, 5, 3, 4, '行政套房视野很棒，独立会客厅方便接待客户，前台办理入住速度很快。', 5, 0, 1, '感谢您的认可，行政套房随时为您预留商务静谧空间。', CONCAT(DATE_SUB(CURDATE(), INTERVAL 4 DAY), ' 10:00:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 5 DAY), ' 16:20:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 4 DAY), ' 10:00:00'), 0),
(4, 2, 4, 2, '标准双床房干净整洁，离地铁1号线步行不到10分钟，出行非常方便。', 5, 0, 1, '感谢肯定，便利交通与干净舒适是我们一直坚持的标准。', CONCAT(DATE_SUB(CURDATE(), INTERVAL 6 DAY), ' 10:00:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 7 DAY), ' 16:20:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 6 DAY), ' 10:00:00'), 0),
(5, 6, 5, 1, '单人出差性价比很高，WiFi 速度稳定，晚上很安静，睡了个好觉。', 4, 0, 1, '感谢反馈，我们会持续优化商旅办公体验。', CONCAT(DATE_SUB(CURDATE(), INTERVAL 8 DAY), ' 10:00:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 9 DAY), ' 16:20:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 8 DAY), ' 10:00:00'), 0),
(6, 7, 6, 3, '智能客服回答押金和停车问题很准确，到店后前台服务也很热情。', 5, 0, 1, '感谢您体验我们的智能客服与前台服务，祝您旅途愉快！', CONCAT(DATE_SUB(CURDATE(), INTERVAL 10 DAY), ' 10:00:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 11 DAY), ' 16:20:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 10 DAY), ' 10:00:00'), 0),
(7, 8, 7, 5, '周末一家三口过来度假，房间宽敞明亮，停车免费这点很加分。', 5, 0, 1, '感谢好评，期待下次周末与您再会！', CONCAT(DATE_SUB(CURDATE(), INTERVAL 13 DAY), ' 10:00:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 14 DAY), ' 16:20:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 13 DAY), ' 10:00:00'), 0),
(8, 9, 8, 4, '浴缸很干净，夜里叫前台送了一床被子 5 分钟就送到了，响应很快。', 5, 0, 1, '24小时快速响应是我们的承诺，欢迎再次入住！', CONCAT(DATE_SUB(CURDATE(), INTERVAL 16 DAY), ' 10:00:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 17 DAY), ' 16:20:00'), CONCAT(DATE_SUB(CURDATE(), INTERVAL 16 DAY), ' 10:00:00'), 0);
